import { useId, type ReactNode } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import './partition-list.css';

export interface PartitionGroup { id: string; label: string; description?: ReactNode; emptyMessage?: ReactNode }
export interface PartitionItem { id: string; groupId: string; label: string; description?: ReactNode; icon?: ReactNode; disabled?: boolean }
export interface PartitionMove { itemId: string; toGroupId: string }
export interface PartitionListProps {
  groups: readonly PartitionGroup[];
  /** Each item belongs to a supplied group; IDs must be unique. Caller order is preserved within groups. */
  items: readonly PartitionItem[];
  onMove: (itemId: string, toGroupId: string) => void;
  pending?: readonly PartitionMove[];
  errors?: Readonly<Record<string, string | undefined>>;
  disabled?: boolean;
  label?: string;
  className?: string;
}

/** Requests a move. Only a new items prop can relocate a row; no optimistic state or timers. */
export function PartitionList({ groups, items, onMove, pending = [], errors = {}, disabled = false,
  label = 'Menu partitions', className = '' }: PartitionListProps) {
  const instance = useId();
  const reducedMotion = useReducedMotion();
  const transition = reducedMotion ? { duration: 0 } : { type: 'spring' as const, stiffness: 320, damping: 25, mass: .8 };
  return <ol className={`mf-partition-list ${className}`} aria-label={label}>
    {groups.flatMap(group => {
      const groupItems = items.filter(item => item.groupId === group.id);
      const groupHeading = `${instance}-${group.id}`;
      return [<motion.li key={`group:${group.id}`} layout={!reducedMotion && 'position'} transition={transition} role="presentation" className="mf-partition-list__group">
        <h3 id={groupHeading}>{group.label}<span aria-label={`${groupItems.length} items`}>{groupItems.length}</span></h3>
        {group.description && <p>{group.description}</p>}
      </motion.li>, ...groupItems.map(item => {
        const move = pending.find(request => request.itemId === item.id);
        const error = errors[item.id];
        return <motion.li key={`item:${item.id}`} data-partition-id={item.id} data-group-id={group.id}
          layout={!reducedMotion && 'position'} initial={false} transition={transition}
          className="mf-partition-list__item" aria-describedby={groupHeading} aria-busy={Boolean(move)}>
          <div className="mf-partition-list__row"><span className="mf-partition-list__icon" aria-hidden="true">{item.icon ?? <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5"><rect x="3" y="4" width="14" height="12" rx="3"/><path d="M7 7v6m3-6h4m-4 3h4"/></svg>}</span>
            <div className="mf-partition-list__copy"><span>{item.label}</span>{item.description && <p>{item.description}</p>}</div>
            <div className="mf-partition-list__destinations" role="group" aria-label={`Partition for ${item.label}`}>
              {groups.map(destination => <motion.button key={destination.id} type="button"
                aria-label={`${destination.label}: ${item.label}`} aria-pressed={group.id === destination.id}
                disabled={disabled || item.disabled || Boolean(move)}
                whileTap={reducedMotion ? undefined : { scale: .97 }}
                onClick={() => { if (destination.id !== group.id) onMove(item.id, destination.id); }}>
                {destination.label}
              </motion.button>)}
            </div>
          </div>
          {move && <p className="mf-partition-list__pending" role="status"><svg aria-hidden="true" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5"><circle cx="8" cy="8" r="5.5" opacity=".25"/><path d="M8 2.5a5.5 5.5 0 0 1 5.5 5.5"/></svg>Moving to {groups.find(candidate => candidate.id === move.toGroupId)?.label ?? move.toGroupId}…</p>}
          {error && <p className="mf-partition-list__error" role="alert">{error}</p>}
        </motion.li>;
      }), ...(!groupItems.length ? [<motion.li key={`empty:${group.id}`} role="presentation" layout={!reducedMotion && 'position'} transition={transition} className="mf-partition-list__empty">{group.emptyMessage ?? 'No items in this partition.'}</motion.li>] : [])];
    })}
  </ol>;
}

.mf-partition-list { display:flex; flex-direction:column; gap:7px; margin:0; padding:0; list-style:none; font:13px/1.4 Inter,system-ui,sans-serif; color:#0a0a0a; }
.mf-partition-list__group { padding:17px 1px 4px; }
.mf-partition-list__group:first-child { padding-top:0; }
.mf-partition-list__group h3 { display:flex; align-items:center; gap:8px; margin:0; font-size:12px; font-weight:550; color:#737373; }
.mf-partition-list__group h3 span { display:grid; place-items:center; min-width:19px; height:18px; padding:0 4px; border-radius:5px; font-size:10px; background:#e5e5e5; color:#525252; font-variant-numeric:tabular-nums; }
.mf-partition-list__group p { margin:4px 0 0; font-size:11px; color:#737373; }
.mf-partition-list__item { position:relative; padding:11px 12px; background:#f5f5f5; border:1px solid transparent; border-radius:11px; }
.mf-partition-list__row { display:flex; gap:10px; align-items:center; min-width:0; }
.mf-partition-list__icon { width:30px; height:30px; flex:0 0 30px; display:grid; place-items:center; color:#525252; background:#fff; border-radius:8px; }
.mf-partition-list__icon svg { width:18px; height:18px; }
.mf-partition-list__copy { min-width:0; flex:1; font-weight:500; overflow-wrap:anywhere; }
.mf-partition-list__copy p { font-size:11px; font-weight:400; color:#6b6b6b; margin:2px 0 0; }
.mf-partition-list__destinations { display:flex; align-items:center; gap:2px; padding:3px; border-radius:8px; background:#fff; flex-shrink:0; }
.mf-partition-list__destinations button { padding:5px 7px; color:#525252; border:0; border-radius:5px; background:transparent; font:inherit; font-size:10px; cursor:pointer; transition:background 140ms,color 140ms; }
.mf-partition-list__destinations button:hover:not(:disabled) { background:#f5f5f5; color:#0a0a0a; }
.mf-partition-list__destinations button[aria-pressed=true],.mf-partition-list__destinations button[aria-pressed=true]:hover:not(:disabled) { background:#e5e5e5; color:#0a0a0a; box-shadow:inset 0 0 0 1px #737373; }
.mf-partition-list__destinations button:focus-visible { outline:2px solid #525252; outline-offset:2px; }
.mf-partition-list__destinations button:disabled { color:#737373; background:#fafafa; cursor:not-allowed; }
.mf-partition-list__destinations button[aria-pressed=true]:disabled { background:#d4d4d4; color:#525252; box-shadow:inset 0 0 0 1px #a3a3a3; }
.mf-partition-list__pending,.mf-partition-list__error { display:flex; align-items:center; gap:6px; margin:9px 0 0 40px; font-size:11px; }
.mf-partition-list__pending { color:#92400e; }
.mf-partition-list__pending svg { width:13px; height:13px; flex-shrink:0; animation:mf-partition-spin 1s linear infinite; }
.mf-partition-list__error { color:#b91c1c; }
.mf-partition-list__empty { padding:14px 12px; color:#737373; font-size:12px; border:1px dashed #d4d4d4; border-radius:10px; }
@keyframes mf-partition-spin { to { transform:rotate(360deg); } }
@media(max-width:520px) { .mf-partition-list__row { flex-wrap:wrap; } .mf-partition-list__destinations { margin-left:40px; } .mf-partition-list__copy { flex-basis:calc(100% - 42px); } }
@media(prefers-reduced-motion:reduce) { .mf-partition-list__destinations button { transition:none; } .mf-partition-list__pending svg { animation:none; } }
